import{_ as e,o as i,c as s,a3 as r}from"./chunks/framework.BU8W3uSP.js";const g=JSON.parse('{"title":"Choosing a history writer","description":"","frontmatter":{"order":10},"headers":[],"relativePath":"writing/history-writers.md","filePath":"writing/history-writers.md"}'),a={name:"writing/history-writers.md"};function o(n,t,d,h,c,p){return i(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="choosing-a-history-writer" tabindex="-1">Choosing a history writer <a class="header-anchor" href="#choosing-a-history-writer" aria-label="Permalink to &quot;Choosing a history writer&quot;">​</a></h1><p>A <em>history writer</em> turns every insert, update and delete of a temporal entity into rows in its history table. Hindsight has two. Both produce the same history table and the same half-open periods, so you can switch between them with one migration.</p><div class="tip custom-block"><p class="custom-block-title">Recommendation: <code>HistoryWriter.Trigger</code></p><p>Use the trigger writer in production. It records every change, including <code>ExecuteUpdate</code>, <code>ExecuteDelete</code>, raw SQL and other processes, and it has no clock-skew exposure. Use the interceptor writer only if the role that applies migrations cannot create functions and triggers.</p></div><div class="language-cs vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cs</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddDbContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AppDbContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> options</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UseNpgsql</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(connectionString)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UseHindsight</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hindsight</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hindsight.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UseHistoryWriter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(HistoryWriter.Trigger)));</span></span></code></pre></div><p><code>UseHindsight()</code> without <code>UseHistoryWriter(...)</code> uses <code>HistoryWriter.Interceptor</code>.</p><h2 id="side-by-side" tabindex="-1">Side by side <a class="header-anchor" href="#side-by-side" aria-label="Permalink to &quot;Side by side&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><a href="/hindsight-efcore/1.4/writing/trigger"><code>HistoryWriter.Trigger</code></a></th><th><a href="/hindsight-efcore/1.4/writing/interceptor"><code>HistoryWriter.Interceptor</code></a></th></tr></thead><tbody><tr><td>Where history is written</td><td>a plpgsql trigger that the migration creates</td><td>a <code>SaveChangesInterceptor</code> in the application</td></tr><tr><td>Records <code>ExecuteUpdate</code>, <code>ExecuteDelete</code>, raw SQL, other processes</td><td>✅ (with <code>NULL</code> change context)</td><td>❌</td></tr><tr><td>Same transaction as the change</td><td>✅ by construction</td><td>✅</td></tr><tr><td>Timestamp</td><td><code>now()</code>, one per transaction</td><td><code>TimeProvider</code>, one per <code>SaveChanges</code></td></tr><tr><td>Concurrent writers, clock skew</td><td>safe</td><td>safe, but a slower clock&#39;s version is dated by the faster one</td></tr><tr><td>An update that sets a column to its current value</td><td>writes nothing</td><td>writes a version</td></tr><tr><td>Extra cost of a delete</td><td>none</td><td>one <code>SELECT … FOR UPDATE</code> per <code>SaveChanges</code></td></tr><tr><td>Can fail after EF Core accepted the changes</td><td>no</td><td>yes, <a href="/hindsight-efcore/1.4/writing/interceptor#if-the-history-write-fails">handled</a></td></tr><tr><td>Needs</td><td>ownership of the table and <code>CREATE</code> on the schema</td><td>nothing beyond writing the tables</td></tr><tr><td>Overhead on a 100-row <code>SaveChanges</code></td><td>+2 to +6 ms</td><td>+7 to +16 ms</td></tr></tbody></table><p>The overhead figures are from the <a href="/hindsight-efcore/1.4/reference/benchmarks">benchmarks</a>; your numbers will differ, but the ratio holds.</p><h2 id="differences-you-can-observe" tabindex="-1">Differences you can observe <a class="header-anchor" href="#differences-you-can-observe" aria-label="Permalink to &quot;Differences you can observe&quot;">​</a></h2><p>Code that runs under both writers can tell them apart in two ways:</p><ul><li><strong>Timestamps.</strong> The interceptor uses your <code>TimeProvider</code>, so a test can inject time. The trigger uses <code>now()</code>.</li><li><strong>No-op updates.</strong> If EF Core marks a property as modified but its value did not change, the interceptor writes a version and the trigger does not, because the trigger compares the old and new row.</li></ul><h2 id="switching-writers" tabindex="-1">Switching writers <a class="header-anchor" href="#switching-writers" aria-label="Permalink to &quot;Switching writers&quot;">​</a></h2><p>Change the option and add a migration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ef</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SwitchToTriggerWriter</span></span></code></pre></div><p>The migration creates the trigger function and trigger (or, when switching back, drops them). It never touches your data or the history table&#39;s columns.</p>`,15)])])}const k=e(a,[["render",o]]);export{g as __pageData,k as default};
